#include <stdio.h>

int main() {
    int a[] = {10, 20, 30, 40, 50};
    int n = 5;

    for (int i = 0; i < n / 2; i++) {
        int temp = a[i];
        a[i] = a[n - i];
        a[n - i] = temp;
    }

    for (int i = 0; i < n; i++) {
        printf("%d ", a[i]);
    }
    return 0;
}

#include <stdio.h>

void swap(int *a, int *b) {
    int *temp;
    *temp = *a;
    *a = *b;
    *b = *temp;
}

int main() {
    int x = 10;
    int y = 20;
    swap(&x, &y);
    printf("%d %d", x, y);
    return 0;
}

